        svg: `<svg viewBox="0 0 1100 1100" xmlns="http://www.w3.org/2000/svg"><rect width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="70" text-anchor="middle" fill="#ffd700" font-size="32" font-weight="bold">THE METER PROBLEM</text><circle cx="300" cy="500" r="140" fill="#6366f1" stroke="#ffd700" stroke-width="3"/><text x="300" y="495" text-anchor="middle" fill="#ffffff" font-size="20" font-weight="bold">BROADCAST</text><text x="300" y="525" text-anchor="middle" fill="#ffffff" font-size="20" font-weight="bold">POWER</text><circle cx="800" cy="500" r="140" fill="#ec4899" stroke="#ffd700" stroke-width="3"/><text x="800" y="495" text-anchor="middle" fill="#ffffff" font-size="20" font-weight="bold">BILLABLE</text><text x="800" y="525" text-anchor="middle" fill="#ffffff" font-size="20" font-weight="bold">UTILITY</text><line x1="440" y1="500" x2="660" y2="500" stroke="#ef4444" stroke-width="5"/><line x1="500" y1="440" x2="600" y2="560" stroke="#ef4444" stroke-width="8"/><line x1="500" y1="560" x2="600" y2="440" stroke="#ef4444" stroke-width="8"/><text x="550" y="380" text-anchor="middle" fill="#ef4444" font-size="22" font-weight="bold">INCOMPATIBLE</text><rect x="200" y="720" width="700" height="280" fill="none" stroke="#ffd700" stroke-width="2"/><text x="550" y="755" text-anchor="middle" fill="#ffd700" font-size="20" font-weight="bold">MORGAN'S CALCULATION</text><text x="230" y="795" fill="#ffffff" font-size="15">Wired electricity: every customer has a meter on their wall.</text><text x="230" y="825" fill="#ffffff" font-size="15">Tesla's broadcast power: anyone with a tuned coil draws current.</text><text x="230" y="855" fill="#ffffff" font-size="15">No exclusion = no bills = no revenue = no return on $150,000.</text><text x="230" y="900" fill="#10b981" font-size="15">Marconi's telegraphy was different: only Marconi's customers</text><text x="230" y="925" fill="#10b981" font-size="15">paid for messages sent through Marconi's stations.</text><text x="230" y="970" fill="#ef4444" font-size="16" font-weight="bold">Verdict: Morgan would fund telegraphy, not free power.</text></svg>`,
